import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/16-NetCore_Design.html","title":"Apollo NetCore 网络模块设计","lang":"en-US","frontmatter":{},"filePathRelative":"16-NetCore_Design.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`16-NetCore_Design.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="apollo-netcore-网络模块设计" tabindex="-1"><a class="header-anchor" href="#apollo-netcore-网络模块设计"><span>Apollo NetCore 网络模块设计</span></a></h1><blockquote><p>目标：替换旧的 SDNet/SSEngine 依赖，提供跨平台（Linux io_uring/epoll、Windows IOCP）的统一网络层，覆盖客户端链路、内部服务通信，并为 Unity/U3D SDK 提供稳定协议。</p></blockquote><h2 id="_1-设计目标" tabindex="-1"><a class="header-anchor" href="#_1-设计目标"><span>1. 设计目标</span></a></h2><ol><li><strong>统一抽象</strong>：上层只依赖 <code>NetCore</code> 接口，底层在 Linux 选择 <code>io_uring</code>（fallback <code>epoll</code>），在 Windows 使用 IOCP。</li><li><strong>消息规范</strong>：定义标准包头、序列号、压缩、加密、去重、QoS；客户端 SDK 与服务器共享 IDL。</li><li><strong>扩展能力</strong>：内置限流、灰度、流量复制、负载均衡 Hook；支持 KCP/WebSocket 等扩展。</li><li><strong>监控/调试</strong>：暴露连接状态、带宽、RTT、错误等指标；提供抓包/注入工具。</li><li><strong>与 Transport 集成</strong>：内网服务间通信可以复用 <code>Transport</code> 层（NNG/SharedMemory），NetCore 专注于客户端链路与高性能 TCP/KCP。</li></ol><h2 id="_2-模块分层" tabindex="-1"><a class="header-anchor" href="#_2-模块分层"><span>2. 模块分层</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌────────────────────────────────────────────┐</span>
<span class="line">│ NetCore API                                │</span>
<span class="line">│  • Connection / Listener / SessionManager  │</span>
<span class="line">│  • MessageCodec / PacketBuilder            │</span>
<span class="line">│  • RateLimiter / QoS / Deduplicator        │</span>
<span class="line">└──────────────┬─────────────────────────────┘</span>
<span class="line">               │</span>
<span class="line">┌──────────────▼──────────────┐   ┌──────────────────────────────┐</span>
<span class="line">│ Linux Backend                │   │ Windows Backend              │</span>
<span class="line">│  io_uring Executor           │   │ IOCP Executor                │</span>
<span class="line">│  epoll (compat)              │   │ WSAPoll (compat)             │</span>
<span class="line">└──────────────┬──────────────┘   └──────────────┬──────────────┘</span>
<span class="line">               │                                   │</span>
<span class="line">        ┌──────▼──────┐                      ┌─────▼──────┐</span>
<span class="line">        │ TCP Driver  │                      │ TCP Driver │</span>
<span class="line">        ├─────────────┤                      ├────────────┤</span>
<span class="line">        │ KCP/UDP     │ (可选)               │ WSAPacket  │</span>
<span class="line">        │ WebSocket   │ (可选)               │ WinHTTP(可选) │</span>
<span class="line">        └─────────────┘                      └────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-核心接口" tabindex="-1"><a class="header-anchor" href="#_3-核心接口"><span>3. 核心接口</span></a></h2><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">struct</span> <span class="token class-name">NetConfig</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">uint32_t</span> workerThreads <span class="token operator">=</span> std<span class="token double-colon punctuation">::</span>thread<span class="token double-colon punctuation">::</span><span class="token function">hardware_concurrency</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    size_t sendBuffer <span class="token operator">=</span> <span class="token number">64</span> <span class="token operator">*</span> <span class="token number">1024</span><span class="token punctuation">;</span></span>
<span class="line">    size_t recvBuffer <span class="token operator">=</span> <span class="token number">64</span> <span class="token operator">*</span> <span class="token number">1024</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">bool</span> enableTLS <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">bool</span> enableKCP <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">bool</span> enableWebSocket <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">uint32_t</span> maxConnections <span class="token operator">=</span> <span class="token number">20000</span><span class="token punctuation">;</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>string certificatePath<span class="token punctuation">;</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>string privateKeyPath<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">INetListener</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token operator">~</span><span class="token function">INetListener</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">bool</span> <span class="token function">Start</span><span class="token punctuation">(</span><span class="token keyword">const</span> NetConfig<span class="token operator">&amp;</span><span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">void</span> <span class="token function">Stop</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">INetConnection</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token operator">~</span><span class="token function">INetConnection</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">bool</span> <span class="token function">Send</span><span class="token punctuation">(</span><span class="token keyword">const</span> <span class="token keyword">void</span><span class="token operator">*</span> data<span class="token punctuation">,</span> size_t len<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">void</span> <span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> ConnectionMetrics <span class="token function">GetMetrics</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">const</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="sessionmanager" tabindex="-1"><a class="header-anchor" href="#sessionmanager"><span>SessionManager</span></a></h3><ul><li>维护连接 ID、心跳、断线重连（支持 token 验证）。</li><li>对接 MessageDispatcher（客户端协议）与 Transport（内网协议）。</li></ul><h3 id="messagecodec-packetbuilder" tabindex="-1"><a class="header-anchor" href="#messagecodec-packetbuilder"><span>MessageCodec / PacketBuilder</span></a></h3><ul><li>包头（16 bytes）：<code>uint16 length</code>, <code>uint16 msg_id</code>, <code>uint32 seq</code>, <code>uint32 ts</code>, <code>uint16 flags</code>, <code>uint16 checksum</code>.</li><li>Flags 包含：压缩、加密、重传标记、保留位。</li><li>支持 Protobuf 序列化、批量包合并、分片。</li></ul><h3 id="ratelimiter-deduplicator" tabindex="-1"><a class="header-anchor" href="#ratelimiter-deduplicator"><span>RateLimiter / Deduplicator</span></a></h3><ul><li>参考 <code>docs/01</code> 中的去重、限流策略，整合到 NetCore 层（带可配置阈值）。</li><li>QoS：优先级队列 + 速率控制（令牌桶/漏桶），配合传输层背压机制。</li></ul><h2 id="_4-linux-backend-设计" tabindex="-1"><a class="header-anchor" href="#_4-linux-backend-设计"><span>4. Linux Backend 设计</span></a></h2><h3 id="_4-1-io-uring" tabindex="-1"><a class="header-anchor" href="#_4-1-io-uring"><span>4.1 io_uring</span></a></h3><ul><li>使用 <code>IORING_SETUP_SQPOLL</code> + <code>IORING_SETUP_COOP_TASKRUN</code> 提高效率。</li><li>提交队列处理：<code>accept</code>, <code>readv</code>, <code>writev</code>, <code>timeout</code>, <code>recvmsg</code> (KCP)。</li><li>Buffer 管理：采用 <code>FixedBuffer</code> + <code>provided buffers</code>（<code>IORING_OP_PROVIDE_BUFFERS</code>），减少内存拷贝。</li><li>若内核版本 &lt; 5.10，则 fallback 到 <code>epoll + eventfd + thread pool</code>。</li></ul><h3 id="_4-2-线程模型" tabindex="-1"><a class="header-anchor" href="#_4-2-线程模型"><span>4.2 线程模型</span></a></h3><ul><li><code>IOThread</code>：少量线程（1-2）负责 <code>io_uring_enter</code>。</li><li><code>WorkerThread</code>：处理业务回调（消息解码、分发），可以复用全局线程池。</li><li>CPU 绑定：高负载场景可 pin 线程到固定核心。</li></ul><h2 id="_5-windows-backend-设计" tabindex="-1"><a class="header-anchor" href="#_5-windows-backend-设计"><span>5. Windows Backend 设计</span></a></h2><h3 id="_5-1-iocp" tabindex="-1"><a class="header-anchor" href="#_5-1-iocp"><span>5.1 IOCP</span></a></h3><ul><li><code>CreateIoCompletionPort</code> + 工作线程池。</li><li>每个连接使用 <code>WSABUF</code> + Overlapped；配合 <code>AcceptEx</code>, <code>ConnectEx</code>.</li><li>支持 <code>DisconnectEx</code> 平滑断开、超时处理。</li></ul><h3 id="_5-2-kcp-websocket-可选" tabindex="-1"><a class="header-anchor" href="#_5-2-kcp-websocket-可选"><span>5.2 KCP/WebSocket (可选)</span></a></h3><ul><li>在 Windows 上封装 KCP（用户态 UDP），或使用 WinSock UDP + io_uring-style overlapped。</li><li>WebSocket 可基于 WinHTTP/WebSocket APIs 或第三方库（libwebsockets），但与 NetCore 解耦，作为可选模块。</li></ul><h2 id="_6-客户端-sdk-接入规范" tabindex="-1"><a class="header-anchor" href="#_6-客户端-sdk-接入规范"><span>6. 客户端 SDK 接入规范</span></a></h2><h3 id="_6-1-sdk-特性" tabindex="-1"><a class="header-anchor" href="#_6-1-sdk-特性"><span>6.1 SDK 特性</span></a></h3><ul><li>Unity/U3D C# SDK 提供：连接/重连、心跳、包头封装、Protobuf 序列化、加密（AES/ChaCha20）与签名、压缩（LZ4）。</li><li>支持 TCP(默认)、KCP(低延迟)、WebSocket(可选)。</li><li>提供 Hook：网络事件（连接成功/失败、断线重连）、消息回调、调试日志。</li></ul><h3 id="_6-2-握手流程" tabindex="-1"><a class="header-anchor" href="#_6-2-握手流程"><span>6.2 握手流程</span></a></h3><ol><li>Client → Gate：<code>Hello</code> 包（ClientVersion、DeviceID、Token、Transport特性）。</li><li>Gate 返回 <code>HelloAck</code>（会话ID、加密参数、心跳间隔）。</li><li>后续消息携带 <code>session_id</code>/<code>seq</code>，心跳包用于保活；断线后客户端可使用会话 Token 重连。</li></ol><h3 id="_6-3-协议规范" tabindex="-1"><a class="header-anchor" href="#_6-3-协议规范"><span>6.3 协议规范</span></a></h3><ul><li>使用同一套 Protobuf IDL（<code>Tool/pb</code>）。</li><li>消息 ID 与枚举由 IDL 自动生成，客户端 SDK 通过 stub 访问。</li><li>SDK 提供 <code>Send&lt;T&gt;(msg_id, message)</code> API，内部封包、压缩、加密。</li></ul><h2 id="_7-安全与加密" tabindex="-1"><a class="header-anchor" href="#_7-安全与加密"><span>7. 安全与加密</span></a></h2><ul><li><strong>传输层</strong>：可选 TLS（OpenSSL / SChannel），在 GateServer 与客户端之间启用。</li><li><strong>应用层</strong>：握手后协商对称密钥（AES-256-GCM / ChaCha20-Poly1305），消息级别加密。</li><li><strong>签名/防篡改</strong>：包头包含 HMAC，防止中间人篡改。</li><li><strong>防刷/限流</strong>：GateServer 结合 IP/QPS 黑名单、令牌桶。</li></ul><h2 id="_8-灰度与流量复制" tabindex="-1"><a class="header-anchor" href="#_8-灰度与流量复制"><span>8. 灰度与流量复制</span></a></h2><ul><li>NetCore 对每个连接维护标签（版本、区域、设备），可由 GateServer 的策略器决定转发到不同 GameServer。</li><li>支持“流量复制”模式：将真实客户端流量复制一份给测试服务器（仅透传，不影响主链路）。</li></ul><h2 id="_9-监控与调试" tabindex="-1"><a class="header-anchor" href="#_9-监控与调试"><span>9. 监控与调试</span></a></h2><ul><li>暴露指标：连接数、带宽、消息速率、RTT、重传、失败率、KCP 滑窗等。</li><li>提供调试端口：可抓取近期包内容（脱敏），或注入测试包。</li><li>日志：关键事件（连接建立/断开、异常、限流触发）写入统一日志模块。</li></ul><h2 id="_10-项目拆分" tabindex="-1"><a class="header-anchor" href="#_10-项目拆分"><span>10. 项目拆分</span></a></h2><ol><li><strong>阶段 1</strong>：TCP (io_uring/IOCP) + 基础包格式 + SessionManager + Unity SDK 初版。</li><li><strong>阶段 2</strong>：KCP/WebSocket 可选模块、TLS/加密、流量复制、限流。</li><li><strong>阶段 3</strong>：零拷贝优化、共享内存直通、SDK 工具链（抓包、调试 UI）。</li><li><strong>阶段 4</strong>：安全增强（HMAC、动态密钥）、自动化压测工具、与 Transport 层联动。</li></ol><hr><p>本设计替代旧有 SDNet 方案，为所有服务和 SDK 提供统一的网络基础，并为后续 AOI/Battle/Transport 等模块提供稳定的数据通道。***</p>`,41)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};